import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv3d_kk1_forward(torch::Tensor x,
                                 torch::Tensor w,
                                 c10::optional<torch::Tensor> b,
                                 int64_t stride,
                                 int64_t padding,
                                 int64_t dilation,
                                 int64_t groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled 3D convolution for kernel (K, K, 1), stride 1, dilation 1, groups 1.
// The input is treated as N*D independent 2D convolutions over the (H, W) plane,
// because the kernel extent along the last dimension is 1.
   // Each block computes a 32x16 output spatial tile for a group of COT output
   // channels of one (n, d) slice, staging the (32+K-1)x(16+K-1) input tile and
   // the corresponding weight tile in shared memory via CuTe tensors.
template <int K>
__global__ void __launch_bounds__(256, 2) conv3d_kk1_kernel(
    const float* __restrict__ X,
    const float* __restrict__ Wt,
    const float* __restrict__ B,
    float* __restrict__ Y,
    int Cin, int H, int Wd, int D,
    int Cout, int Hout, int Wout, int Dout,
    int padding)
{
  constexpr int TH      = 32;
  constexpr int TW      = 16;
  constexpr int COT     = 4;
  constexpr int DV      = 4;
  // 256 threads: depth (DV) x column (TW) x 4 row groups. With only four
  // row groups spanning the 32-row tile, each thread owns TR = 8
  // consecutive output rows (see below), doubling per-thread register
  // blocking versus a 512-thread block while keeping two blocks per SM.
  constexpr int Threads = (TH * TW) / 2;
  constexpr int IH      = TH + K - 1;
  constexpr int IW      = TW + K - 1;

  const int tid = threadIdx.x;

  // Global strides for contiguous (N, C, H, W, D) layout
  const int64_t sXn = (int64_t)Cin * H * Wd * D;
  const int64_t sXc = (int64_t)H * Wd * D;
  const int64_t sXh = (int64_t)Wd * D;
  const int64_t sXw = (int64_t)D;

  const int64_t sYn = (int64_t)Cout * Hout * Wout * Dout;
  const int64_t sYc = (int64_t)Hout * Wout * Dout;
  const int64_t sYh = (int64_t)Wout * Dout;
  const int64_t sYw = (int64_t)Dout;

  // Tile coordinates
  const int tiles_x = (Wout + TW - 1) / TW;
  const int tile_y  = blockIdx.x / tiles_x;
  const int tile_x  = blockIdx.x - tile_y * tiles_x;
  const int oh0     = tile_y * TH;
  const int ow0     = tile_x * TW;

  // Slice coordinate: blockIdx.y covers one batch item and DV adjacent depth slices.
  // The last tensor dimension is contiguous, so grouping depths improves global
  // load/store efficiency for the kernel-size-1 dimension.
  const int d_chunks = (Dout + DV - 1) / DV;
  const int b        = blockIdx.y;
  const int n        = b / d_chunks;
  const int d_chunk  = b - n * d_chunks;
  const int d_out0   = d_chunk * DV;

  // Reuse the staged input tile across all output-channel groups in this block;
  // co0 is advanced sequentially below instead of using blockIdx.z, which
  // removes redundant global input-tile loads for the z grid dimension.

  // Thread mapping: depth (j) is the fastest dimension, then output column
  // (tw), then one of four row groups (tq). Each thread owns TR consecutive
  // output rows for a single (column, depth) pair. Consecutive threads thus
  // write nearly-contiguous global addresses for every (channel, row) store
  // (coalesced stores instead of stride-Dout scatter), and shared-memory
  // input reads are bank-conflict free (32 consecutive banks per warp).
  constexpr int TR = TH / (Threads / (TW * DV));
  const int j  = tid % DV;
  const int tw = (tid / DV) % TW;
  const int tq = tid / (DV * TW);
  const int ow = ow0 + tw;
  const int d_out = d_out0 + j;
  const bool p_valid = (ow < Wout) && (d_out < Dout) && (oh0 + tq * TR < Hout);

  Tensor mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                          make_shape(Cout, Hout, Wout, Dout),
                          make_stride(sYc, sYh, sYw, Int<1>{}));
  Tensor mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                          make_shape(Cin, H, Wd, D),
                          make_stride(sXc, sXh, sXw, Int<1>{}));
  Tensor mW = make_tensor(make_gmem_ptr(Wt),
                          make_shape(Cout, Cin, Int<K>{}, Int<K>{}),
                          make_stride((int64_t)Cin * (K * K), Int<K * K>{}, Int<K>{}, Int<1>{}));

  // Dynamic shared memory: input tile for DV depths followed by weight tile
  extern __shared__ float smem[];
  float* sX_ptr = smem;
  float* sW_ptr = smem + (size_t)Cin * IH * IW * DV;
  Tensor sX = make_tensor(make_smem_ptr(sX_ptr),
                          make_shape(Cin, Int<IH>{}, Int<IW>{}, Int<DV>{}),
                          make_stride(Int<IH * IW * DV>{}, Int<IW * DV>{}, Int<DV>{}, Int<1>{}));
  Tensor sW = make_tensor(make_smem_ptr(sW_ptr),
                          make_shape(Int<COT>{}, Cin, Int<K>{}, Int<K>{}),
                          make_stride(Cin * (K * K), Int<K * K>{}, Int<K>{}, Int<1>{}));

  // Stage the input tile cooperatively (zero-filled halo for padding/borders)
  const int sX_total = Cin * IH * IW * DV;
  for (int idx = tid; idx < sX_total; idx += Threads) {
    int j  = idx % DV;
    int iw = (idx / DV) % IW;
    int ih = (idx / (DV * IW)) % IH;
    int ci = idx / (DV * IH * IW);
    int gh = oh0 + ih - padding;
    int gw = ow0 + iw - padding;
    int d_in = d_out0 + j - padding;
    float v = 0.f;
    if ((unsigned)gh < (unsigned)H && (unsigned)gw < (unsigned)Wd &&
        (unsigned)d_in < (unsigned)D) {
      v = mX(ci, gh, gw, d_in);
    }
    sX(ci, ih, iw, j) = v;
  }

  __syncthreads(); // input tile is resident; reuse it for every output-channel group
  // Stage only one COT weight group at a time, but keep the much larger input
  // tile fixed in shared memory while looping over all output channels. This
  // raises shared-memory reuse and cuts global input traffic by Cout/COT.
  const int sW_total = COT * Cin * K * K;
  for (int co0 = 0; co0 < Cout; co0 += COT) {
    for (int idx = tid; idx < sW_total; idx += Threads) {
      int kw = idx % K;
      int kh = (idx / K) % K;
      int ci = (idx / (K * K)) % Cin;
      int co = idx / (K * K * Cin);
      int co_g = co0 + co;
      float v = 0.f;
      if (co_g < Cout) v = mW(co_g, ci, kh, kw);
      sW(co, ci, kh, kw) = v;
    }
    __syncthreads();
    if (p_valid) {
      // Accumulate COT output channels for TR output rows at one (column, depth).
      // Register blocking is TR x COT = 8 x 8 = 64 accumulators per thread, so
      // every shared-memory input value feeds COT FMAs and every weight value
      // feeds TR FMAs. The input tile is now additionally reused across all
      // output-channel groups instead of being refetched for each z block.
      float acc[COT][TR];
      #pragma unroll
      for (int co = 0; co < COT; ++co) {
        int co_g = co0 + co;
        float bv = (B != nullptr && co_g < Cout) ? B[co_g] : 0.f;
        #pragma unroll
        for (int r = 0; r < TR; ++r) {
          acc[co][r] = bv;
        }
      }
      for (int ci = 0; ci < Cin; ++ci) {
        #pragma unroll
        for (int kh = 0; kh < K; ++kh) {
          #pragma unroll
          for (int kw = 0; kw < K; ++kw) {
            float xv[TR];
            #pragma unroll
            for (int r = 0; r < TR; ++r) {
              xv[r] = sX(ci, tq * TR + r + kh, tw + kw, j);
            }
            #pragma unroll
            for (int co = 0; co < COT; ++co) {
              float wv = sW(co, ci, kh, kw);
              #pragma unroll
              for (int r = 0; r < TR; ++r) {
                acc[co][r] = fmaf(xv[r], wv, acc[co][r]);
              }
            }
          }
        }
      }
      // Outputs are written exactly once and never re-read by this kernel, so use
      // streaming stores to avoid polluting L1/L2 and reduce pressure on the
      // memory pipe for this output-volume-dominated convolution.
      #pragma unroll
      for (int co = 0; co < COT; ++co) {
        int co_g = co0 + co;
        if (co_g < Cout) {
          #pragma unroll
          for (int r = 0; r < TR; ++r) {
            int oh = oh0 + tq * TR + r;
            if (oh < Hout) __stwt(&mY(co_g, oh, ow, d_out), acc[co][r]);
          }
        }
      }
    }
    __syncthreads(); // all threads are done before the next weight-group overwrite
  }
}

namespace {

template <int K>
void launch_conv3d_kk1(const float* X, const float* Wt, const float* B, float* Y,
                       int N, int Cin, int H, int Wd, int D,
                       int Cout, int Hout, int Wout, int Dout,
                       int padding, cudaStream_t stream)
{
  constexpr int TH  = 32;
  constexpr int TW  = 16;
  constexpr int COT = 4;
  constexpr int DV  = 4;
  constexpr int IH  = TH + K - 1;
  constexpr int IW  = TW + K - 1;

  const int tiles_x = (Wout + TW - 1) / TW;
  const int tiles_y = (Hout + TH - 1) / TH;

  // 256 threads per block: only four row groups span the 32-row tile, so
  // each thread owns TR = 8 output rows (8x8 = 64 accumulators), doubling
  // per-thread register blocking while still allowing two blocks per SM.
  dim3 block((TH * TW) / 2);
  const int d_chunks = (Dout + DV - 1) / DV;
  dim3 grid(tiles_x * tiles_y, N * d_chunks, 1);

  size_t smem = ((size_t)Cin * IH * IW * DV + (size_t)COT * Cin * K * K) * sizeof(float);
  if (smem > 48 * 1024) {
    cudaFuncSetAttribute(conv3d_kk1_kernel<K>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                         (int)smem);
  }

  conv3d_kk1_kernel<K><<<grid, block, smem, stream>>>(
      X, Wt, B, Y, Cin, H, Wd, D, Cout, Hout, Wout, Dout, padding);
}

} // namespace

torch::Tensor conv3d_kk1_forward(torch::Tensor x,
                                 torch::Tensor w,
                                 c10::optional<torch::Tensor> b,
                                 int64_t stride,
                                 int64_t padding,
                                 int64_t dilation,
                                 int64_t groups)
{
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
              "x and w must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be [N, C, H, W, D]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cout, Cin, K, K, 1]");
  TORCH_CHECK(groups == 1, "only groups == 1 is supported");
  TORCH_CHECK(stride == 1, "only stride == 1 is supported");
  TORCH_CHECK(dilation == 1, "only dilation == 1 is supported");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  const int64_t K = w.size(2);
  TORCH_CHECK(w.size(3) == K && w.size(4) == 1, "kernel must be (K, K, 1)");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  const int64_t N    = x_c.size(0);
  const int64_t Cin  = x_c.size(1);
  const int64_t H    = x_c.size(2);
  const int64_t Wd   = x_c.size(3);
  const int64_t D    = x_c.size(4);
  const int64_t Cout = w_c.size(0);
  TORCH_CHECK(w_c.size(1) == Cin, "w.size(1) must equal in_channels");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.is_cuda() && b_c.scalar_type() == at::kFloat,
                "bias must be a CUDA float32 tensor");
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  const int64_t Hout = H + 2 * padding - K + 1;
  const int64_t Wout = Wd + 2 * padding - K + 1;
  const int64_t Dout = D + 2 * padding;
  TORCH_CHECK(Hout > 0 && Wout > 0 && Dout > 0, "invalid output size");

  auto y = torch::empty({N, Cout, Hout, Wout, Dout}, x.options());

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  const float* Xp  = x_c.data_ptr<float>();
  const float* Wp  = w_c.data_ptr<float>();
  float*       Yp  = y.data_ptr<float>();

  switch (K) {
    case 1:
      launch_conv3d_kk1<1>(Xp, Wp, b_ptr, Yp, (int)N, (int)Cin, (int)H, (int)Wd, (int)D,
                           (int)Cout, (int)Hout, (int)Wout, (int)Dout, (int)padding, stream);
      break;
    case 3:
      launch_conv3d_kk1<3>(Xp, Wp, b_ptr, Yp, (int)N, (int)Cin, (int)H, (int)Wd, (int)D,
                           (int)Cout, (int)Hout, (int)Wout, (int)Dout, (int)padding, stream);
      break;
    case 5:
      launch_conv3d_kk1<5>(Xp, Wp, b_ptr, Yp, (int)N, (int)Cin, (int)H, (int)Wd, (int)D,
                           (int)Cout, (int)Hout, (int)Wout, (int)Dout, (int)padding, stream);
      break;
    case 7:
      launch_conv3d_kk1<7>(Xp, Wp, b_ptr, Yp, (int)N, (int)Cin, (int)H, (int)Wd, (int)D,
                           (int)Cout, (int)Hout, (int)Wout, (int)Dout, (int)padding, stream);
      break;
    default:
      TORCH_CHECK(false, "unsupported kernel size K = ", K, " (supported: 1, 3, 5, 7)");
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv3d_kk1_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

conv3d_ext = load_inline(
    name="cute_conv3d_kk1_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv3d_kk1_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    3D convolution with kernel (kernel_size, kernel_size, 1) implemented with a
    single cooperative tiled CUDA kernel written with CuTe.

    Parameters are held in an nn.Conv3d module so that initialization and
    state_dict layout exactly match the reference Model, while forward() runs
    entirely on the custom CuTe kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        k = kernel_size[0] if isinstance(kernel_size, (tuple, list)) else kernel_size
        self.conv3d = nn.Conv3d(in_channels, out_channels, (k, k, 1),
                                stride=stride, padding=padding,
                                dilation=dilation, groups=groups, bias=bias)
        self._ext = conv3d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            return self.conv3d(x)
        return self._ext.conv3d_kk1_forward(
            x,
            self.conv3d.weight,
            self.conv3d.bias,
            self.conv3d.stride[0],
            self.conv3d.padding[0],
            self.conv3d.dilation[0],
            self.conv3d.groups,
        )

