import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv3d_kk1_forward(torch::Tensor x,
                                 torch::Tensor w,
                                 c10::optional<torch::Tensor> b,
                                 int64_t stride,
                                 int64_t padding,
                                 int64_t dilation,
                                 int64_t groups);
