cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled 3D convolution for kernel (K, K, 1), stride 1, dilation 1, groups 1.
// The input is treated as N*D independent 2D convolutions over the (H, W) plane,
// because the kernel extent along the last dimension is 1.
   // Each block computes a 32x16 output spatial tile for a group of COT output
   // channels of one (n, d) slice, staging the (32+K-1)x(16+K-1) input tile and
   // the corresponding weight tile in shared memory via CuTe tensors.
template <int K>
__global__ void __launch_bounds__(256, 2) conv3d_kk1_kernel(
    const float* __restrict__ X,
    const float* __restrict__ Wt,
    const float* __restrict__ B,
    float* __restrict__ Y,
    int Cin, int H, int Wd, int D,
    int Cout, int Hout, int Wout, int Dout,
    int padding)
{
  constexpr int TH      = 32;
  constexpr int TW      = 16;
  constexpr int COT     = 8;
  constexpr int DV      = 4;
  // 256 threads: depth (DV) x column (TW) x 4 row groups. With only four
  // row groups spanning the 32-row tile, each thread owns TR = 8
  // consecutive output rows (see below), doubling per-thread register
  // blocking versus a 512-thread block while keeping two blocks per SM.
  constexpr int Threads = (TH * TW) / 2;
  constexpr int IH      = TH + K - 1;
  constexpr int IW      = TW + K - 1;

  const int tid = threadIdx.x;

  // Global strides for contiguous (N, C, H, W, D) layout
  const int64_t sXn = (int64_t)Cin * H * Wd * D;
  const int64_t sXc = (int64_t)H * Wd * D;
  const int64_t sXh = (int64_t)Wd * D;
  const int64_t sXw = (int64_t)D;

  const int64_t sYn = (int64_t)Cout * Hout * Wout * Dout;
  const int64_t sYc = (int64_t)Hout * Wout * Dout;
  const int64_t sYh = (int64_t)Wout * Dout;
  const int64_t sYw = (int64_t)Dout;

  // Tile coordinates
  const int tiles_x = (Wout + TW - 1) / TW;
  const int tile_y  = blockIdx.x / tiles_x;
  const int tile_x  = blockIdx.x - tile_y * tiles_x;
  const int oh0     = tile_y * TH;
  const int ow0     = tile_x * TW;

  // Slice coordinate: blockIdx.y covers one batch item and DV adjacent depth slices.
  // The last tensor dimension is contiguous, so grouping depths improves global
  // load/store efficiency for the kernel-size-1 dimension.
  const int d_chunks = (Dout + DV - 1) / DV;
  const int b        = blockIdx.y;
  const int n        = b / d_chunks;
  const int d_chunk  = b - n * d_chunks;
  const int d_out0   = d_chunk * DV;

  // Reuse the staged input tile across all output-channel groups in this block;
  // co0 is advanced sequentially below instead of using blockIdx.z, which
  // removes redundant global input-tile loads for the z grid dimension.

  // Thread mapping: depth (j) is the fastest dimension, then output column
  // (tw), then one of four row groups (tq). Each thread owns TR consecutive
  // output rows for a single (column, depth) pair. Consecutive threads thus
  // write nearly-contiguous global addresses for every (channel, row) store
  // (coalesced stores instead of stride-Dout scatter), and shared-memory
  // input reads are bank-conflict free (32 consecutive banks per warp).
  constexpr int TR = TH / (Threads / (TW * DV));
  const int j  = tid % DV;
  const int tw = (tid / DV) % TW;
  const int tq = tid / (DV * TW);
  const int ow = ow0 + tw;
  const int d_out = d_out0 + j;
  const bool p_valid = (ow < Wout) && (d_out < Dout) && (oh0 + tq * TR < Hout);

  Tensor mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                          make_shape(Cout, Hout, Wout, Dout),
                          make_stride(sYc, sYh, sYw, Int<1>{}));
  Tensor mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                          make_shape(Cin, H, Wd, D),
                          make_stride(sXc, sXh, sXw, Int<1>{}));
  Tensor mW = make_tensor(make_gmem_ptr(Wt),
                          make_shape(Cout, Cin, Int<K>{}, Int<K>{}),
                          make_stride((int64_t)Cin * (K * K), Int<K * K>{}, Int<K>{}, Int<1>{}));

  // Dynamic shared memory: input tile for DV depths followed by weight tile
  extern __shared__ float smem[];
  float* sX_ptr = smem;
  float* sW_ptr = smem + (size_t)Cin * IH * IW * DV;
  Tensor sX = make_tensor(make_smem_ptr(sX_ptr),
                          make_shape(Cin, Int<IH>{}, Int<IW>{}, Int<DV>{}),
                          make_stride(Int<IH * IW * DV>{}, Int<IW * DV>{}, Int<DV>{}, Int<1>{}));
  Tensor sW = make_tensor(make_smem_ptr(sW_ptr),
                          make_shape(Int<COT>{}, Cin, Int<K>{}, Int<K>{}),
                          make_stride(Cin * (K * K), Int<K * K>{}, Int<K>{}, Int<1>{}));

  // Stage the input tile cooperatively (zero-filled halo for padding/borders)
  const int sX_total = Cin * IH * IW * DV;
  for (int idx = tid; idx < sX_total; idx += Threads) {
    int j  = idx % DV;
    int iw = (idx / DV) % IW;
    int ih = (idx / (DV * IW)) % IH;
    int ci = idx / (DV * IH * IW);
    int gh = oh0 + ih - padding;
    int gw = ow0 + iw - padding;
    int d_in = d_out0 + j - padding;
    float v = 0.f;
    if ((unsigned)gh < (unsigned)H && (unsigned)gw < (unsigned)Wd &&
        (unsigned)d_in < (unsigned)D) {
      v = mX(ci, gh, gw, d_in);
    }
    sX(ci, ih, iw, j) = v;
  }

  __syncthreads(); // input tile is resident; reuse it for every output-channel group
  // Stage only one COT weight group at a time, but keep the much larger input
  // tile fixed in shared memory while looping over all output channels. This
  // raises shared-memory reuse and cuts global input traffic by Cout/COT.
  const int sW_total = COT * Cin * K * K;
  for (int co0 = 0; co0 < Cout; co0 += COT) {
    for (int idx = tid; idx < sW_total; idx += Threads) {
      int kw = idx % K;
      int kh = (idx / K) % K;
      int ci = (idx / (K * K)) % Cin;
      int co = idx / (K * K * Cin);
      int co_g = co0 + co;
      float v = 0.f;
      if (co_g < Cout) v = mW(co_g, ci, kh, kw);
      sW(co, ci, kh, kw) = v;
    }
    __syncthreads();
    if (p_valid) {
